const isProperPrefix = (a, b) => a.length < b.length && a.every((t, i) => t === b[i]);

function tryParse(pointer) {
  if (typeof pointer !== 'string') return null;
  try {
    return parsePointer(pointer);
  } catch {
    return null;
  }
