  if (kind === 'move' && isProperPrefix(from, path)) return 'cannot move into own child';
  return { kind, path, from, value: op.value };
}

function applyOne(doc, { kind, path, from, value }) {
  switch (kind) {
    case 'add':
      return addAt(doc, path, deepCopy(value));
    case 'remove':
